CREATE SCHEMA sales;
CREATE TABLE sales.customers (tenant_id integer NOT NULL, id integer NOT NULL, name varchar(80) DEFAULT 'new', PRIMARY KEY (tenant_id,id));
CREATE TABLE sales.orders (tenant_id integer NOT NULL,id integer GENERATED BY DEFAULT AS IDENTITY,customer_id integer NOT NULL,amount numeric(18,2) DEFAULT 0, doubled numeric GENERATED ALWAYS AS (amount*2) STORED,CONSTRAINT orders_pkey PRIMARY KEY(tenant_id,id),CONSTRAINT orders_customer_fk FOREIGN KEY(tenant_id,customer_id) REFERENCES sales.customers(tenant_id,id) ON DELETE RESTRICT,CONSTRAINT amount_positive CHECK(amount>=0));
CREATE INDEX orders_amount_idx ON sales.orders(amount DESC NULLS LAST) INCLUDE(customer_id) WHERE amount>0;
COMMENT ON TABLE sales.orders IS 'Orders metadata fixture';
COMMENT ON COLUMN sales.orders.amount IS 'Order amount';
CREATE VIEW sales.order_totals AS SELECT tenant_id,sum(amount) AS total FROM sales.orders GROUP BY tenant_id;
